-- Hand-written: the Phase 0 review of Hacker News and SAM.gov for the Web Scraping & Discovery
-- Engine (2026-11-18). Only `approved` sources run; SAM.gov also needs SAM_GOV_API_KEY.
INSERT INTO "sources" ("slug", "name", "type", "authorization_status", "terms_url", "notes") VALUES
  ('hacker_news', 'Hacker News', 'community_api', 'approved', 'https://hn.algolia.com/api', 'Public HN Search API (Algolia), no key; hn.algolia.com has no robots.txt. Reads the monthly "Who is hiring?" thread (each company''s post a job), the "Freelancer? Seeking freelancer?" thread (SEEKING FREELANCER posts as buyer requests) and Ask HN posts asking for an agency or developer: a few requests per run, twice a day. The commonly cited limit is 10,000 requests an hour per IP (third-party figure). The same API the LeadGen Engine''s Hacker News provider uses. Approved 2026-11-18 (Phase 0 review).'),
  ('sam_gov', 'SAM.gov contract opportunities', 'procurement', 'approved', 'https://open.gsa.gov/api/get-opportunities-public-api/', 'US federal contract opportunities through GSA''s Get Opportunities Public API; public data of the US government. Needs a free key (SAM.gov Account Details, SAM_GOV_API_KEY); without one it does not run. A personal key may allow only about 10 calls a day, so it runs once a day and makes at most 3 calls. Keeps open solicitations, presolicitations and sources-sought notices in IT, web, design and marketing NAICS codes, or titled as such work; no contracting officers'' names or emails. Approved 2026-11-18 (Phase 0 review).')
ON CONFLICT ("slug") DO NOTHING;
